export class EntityOps extends Map {
    decodeOp(r, opID) {
        let op = this.getOrCreate(opID);
        op.text = r.stringNullHidden();
    }
    decodeSubOp(r) {
        let op = this.getOrCreate(r.u8(), r.u8());
        op.text = r.string();
    }
    decodeConditionalOp(r) {
        let op = this.getOrCreate(r.u8());
        let varp = r.u16();
        let varbit = r.u16();
        let cop = {
            min: r.i32(),
            max: r.i32(),
            text: r.string(),
        };
        if (varp != 0xFFFF) {
            cop.varp = varp;
        }
        if (varbit != 0xFFFF) {
            cop.varbit = varbit;
        }
        (op.conditionals ??= []).push(cop);
    }
    decodeConditionalSubOp(r) {
        let op = this.getOrCreate(r.u8(), r.u16());
        let varp = r.u16();
        let varbit = r.u16();
        let cop = {
            min: r.i32(),
            max: r.i32(),
            text: r.string(),
        };
        if (varp != 0xFFFF) {
            cop.varp = varp;
        }
        if (varbit != 0xFFFF) {
            cop.varbit = varbit;
        }
        (op.conditionals ??= []).push(cop);
    }
    getOrCreate(index, subIndex) {
        let v = this.get(index);
        if (!v) {
            this.set(index, v = {});
        }
        if (subIndex == null) {
            return v;
        }
        return (v.subs ??= new EntityOps())
            .getOrCreate(subIndex);
    }
}
